```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let question = bound_question(query.query.question);
        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

/// Enforces `ensures len(question) <= 512`. The `requires` already holds for
/// every input, so this is a defensive bound that leaves valid input unchanged.
fn bound_question(question: String) -> String {
    if question.chars().count() <= MAX_QUESTION_CHARS {
        question
    } else {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

export!(Node);
